	"pe/pucp/tesis/migodcu/view/Inicio.view.xml":'<mvc:View controllerName="pe.pucp.tesis.migodcu.controller.Inicio"\n    xmlns:mvc="sap.ui.core.mvc" xmlns="sap.m"><Page id="pageInicio" title="{i18n>inicioTitulo}"><headerContent><Button id="btnAyudaInicio" icon="sap-icon://sys-help" tooltip="{i18n>ayudaTitulo}" press=".onAyuda"/></headerContent><VBox class="sapUiMediumMargin"><Title text="{i18n>grupoAlmacen}" titleStyle="H2" class="sapUiSmallMarginBottom"/><HBox wrap="Wrap"><GenericTile id="tile101" class="sapUiTinyMarginEnd sapUiTinyMarginBottom"\n                    header="{i18n>tile101Titulo}" subheader="{i18n>tile101Subtitulo}" press=".onIrEntrada"><TileContent footer="{i18n>tile101Pie}"><ImageContent src="sap-icon://shipping-status"/></TileContent></GenericTile><GenericTile id="tile261" class="sapUiTinyMarginEnd sapUiTinyMarginBottom"\n                    header="{i18n>tile261Titulo}" subheader="{i18n>tile261Subtitulo}" press=".onIrSalida"><TileContent footer="{i18n>tile261Pie}"><ImageContent src="sap-icon://factory"/></TileContent></GenericTile></HBox></VBox></Page></mvc:View>\n',
	"pe/pucp/tesis/migodcu/view/Resultado.view.xml":'<mvc:View controllerName="pe.pucp.tesis.migodcu.controller.Resultado"\n    xmlns:mvc="sap.ui.core.mvc" xmlns="sap.m" xmlns:core="sap.ui.core"><Page id="pageResultado" title="{= ${resultado>/flujo} === \'salida\' ? ${i18n>tituloSalida} : ${i18n>tituloEntrada} }"><headerContent><Button id="btnAyudaResultado" icon="sap-icon://sys-help" tooltip="{i18n>ayudaTitulo}" press=".onAyuda"/></headerContent><VBox alignItems="Center" class="sapUiLargeMarginTop"><core:Icon src="sap-icon://sys-enter-2" color="Positive" size="2rem"/><Title text="{resultado>/titulo}" titleStyle="H2" class="sapUiSmallMarginTop"/><HBox alignItems="Center" class="sapUiSmallMarginTop"><Title id="txtDocumento" text="{resultado>/textoDocumento}" titleStyle="H1"/><Link text="{i18n>copiarNumero}" press=".onCopiar" class="sapUiSmallMarginBegin"/></HBox><Text text="{resultado>/detalle}" class="sapUiSmallMarginTop"/><MessageStrip id="msAnulacion" type="Information" showIcon="true" text="{resultado>/textoAnulacion}"\n                class="sapUiSmallMarginTop" width="40rem"/><HBox class="sapUiMediumMarginTop"><Button text="{resultado>/textoOtra}" type="Emphasized" press=".onOtra"/><Button text="{i18n>btnVolverInicio}" press=".onVolverInicio" class="sapUiSmallMarginBegin"/></HBox></VBox></Page></mvc:View>\n',
